<?php
require_once __DIR__ . '/statistics.php';
$from = (string)($_GET['from'] ?? date('Y-m-d', strtotime('-29 days')));
$to = (string)($_GET['to'] ?? date('Y-m-d'));
if (!validDate($from) || !validDate($to) || $from > $to || $to > date('Y-m-d')) {
    $from = date('Y-m-d', strtotime('-29 days')); $to = date('Y-m-d');
    echo '<div class="notice error" role="alert">Choose a valid range ending today or earlier. Showing the last 30 days.</div>';
}
$history = all('SELECT * FROM entries ORDER BY experienced_on, id');
$stats = symptomStatistics($symptoms, $history, $from, $to, date('Y-m-d'));
$selected = array_filter($history, fn($e) => $e['experienced_on'] >= $from && $e['experienced_on'] <= $to);
$average = $selected ? array_sum(array_column($selected, 'strength')) / count($selected) : null;
$trend = all('SELECT experienced_on, ROUND(AVG(strength),1) AS average FROM entries WHERE experienced_on BETWEEN ? AND ? GROUP BY experienced_on ORDER BY experienced_on', [$from,$to]);
?>
<section class="page-heading"><div><p class="eyebrow">SEE THE BIGGER PICTURE</p><h1>Your patterns, over time.</h1><p>Frequency, shared days and changes in your recorded symptoms.</p></div></section>
<form method="get" class="card stats-filter"><input type="hidden" name="page" value="stats"><div><label for="from">From</label><input type="date" id="from" name="from" required max="<?= date('Y-m-d') ?>" value="<?= e($from) ?>"></div><div><label for="to">To</label><input type="date" id="to" name="to" required max="<?= date('Y-m-d') ?>" value="<?= e($to) ?>"></div><button class="button primary" type="submit">Update statistics</button><a class="text-link" href="?page=stats">Last 30 days</a></form>
<div class="metric-grid"><article class="metric"><span>Diary entries</span><strong><?= count($selected) ?></strong><small>In the selected period</small></article><article class="metric"><span>Days recorded</span><strong><?= $stats['recorded_days'] ?><em>/ <?= $stats['calendar_days'] ?></em></strong><small>Calendar days with any diary entry</small></article><article class="metric"><span>Average strength</span><strong><?= $average === null ? '—' : number_format($average,1) ?><em>/ 10</em></strong><small>Across all entries in the period</small></article></div>
<div class="notice">A missing diary day means “not recorded”, not “no symptoms”. Frequency uses days with any diary entry. Multiple entries for the same symptom on one date count as one symptom day. Patterns describe your records, not causes or a diagnosis.</div>
<?php if (!$selected): ?><section class="card empty"><h2>Patterns take a little time</h2><p>No entries in this range. Add a check-in or choose a different period.</p><a class="button secondary" href="?page=log">Log a symptom</a></section><?php endif ?>
<section class="card"><div class="section-heading"><div><h2>Symptom frequency</h2><p>In the selected period. Percentages use <?= $stats['recorded_days'] ?> recorded days, not all calendar days.</p></div></div><div class="table-scroll"><table><thead><tr><th scope="col">Symptom</th><th scope="col">Symptom days</th><th scope="col">Share of recorded days</th><th scope="col">Entries</th><th scope="col">Avg. daily strength</th></tr></thead><tbody><?php foreach ($stats['symptoms'] as $s): ?><tr><th scope="row"><?= e($s['name']) ?></th><td><?= $s['days'] ?></td><td><?= $s['share'] === null ? '—' : number_format($s['share'],0) . '%' ?></td><td><?= $s['entries'] ?></td><td><?= $s['average'] === null ? '—' : number_format($s['average'],1) . ' / 10' ?></td></tr><?php endforeach ?></tbody></table></div><?php if (!$symptoms): ?><p class="footnote">Create a symptom and log entries to start building your statistics.</p><?php endif ?></section>
<?php if ($trend): ?><section class="card"><div class="section-heading"><div><h2>Strength over time</h2><p>Average across entries on each recorded day; missing days are omitted.</p></div></div><div class="chart" aria-label="Daily average symptom strength"><?php foreach ($trend as $day): ?><div class="chart-column"><span><?= e($day['average']) ?></span><div class="bar-track"><meter min="0" max="10" value="<?= e($day['average']) ?>"><?= e($day['average']) ?> out of 10</meter><div class="bar bar-<?= (int)round($day['average']*10) ?>"></div></div><small><?= e((new DateTimeImmutable($day['experienced_on']))->format('j M')) ?></small></div><?php endforeach ?></div></section><?php endif ?>
<section class="card"><div class="section-heading"><div><h2>Recorded together</h2><p>Same calendar date, which does not necessarily mean the same time. Each date counts once.</p></div></div>
<p class="footnote">At least 3 shared days and 5 days with either symptom are needed before showing a percentage. This is a descriptive starting point, not a statistical significance test.</p>
<?php if (!$stats['pairs']): ?><div class="empty"><h3>Not enough data for pairs yet</h3><p>Record at least two different symptoms to compare their dates.</p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th scope="col">Symptoms</th><th scope="col">Shared days</th><th scope="col">Days with either</th><th scope="col">Shared-day pattern</th></tr></thead><tbody><?php foreach ($stats['pairs'] as $pair): ?><tr><th scope="row"><?= e($pair['a']) ?> + <?= e($pair['b']) ?></th><td><?= $pair['shared'] ?></td><td><?= $pair['union'] ?></td><td><?= $pair['ready'] ? number_format($pair['share'],0) . '% of days with either' : 'Still collecting data' ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
<section class="card"><div class="section-heading"><div><h2>Is anything changing?</h2><p>Compares equal windows at the start and end of your selected range.</p></div></div>
<?php if ($stats['half']): ?><p class="footnote">Earlier: <?= e(dateLabel($from)) ?>–<?= e(dateLabel($stats['early_end'])) ?> (<?= $stats['early_recorded'] ?> recorded days). Later: <?= e(dateLabel($stats['late_start'])) ?>–<?= e(dateLabel($to)) ?> (<?= $stats['late_recorded'] ?> recorded days). <?= $stats['calendar_days'] % 2 ? 'The middle day is omitted to keep windows equal.' : '' ?></p><?php endif ?>
<p class="footnote">Frequency needs at least 7 calendar days and 3 recorded days in each window. Strength also needs this symptom on 3 days in each window. These are minimum data rules, not proof of a trend. Changes in logging can affect the comparison.</p>
<div class="table-scroll"><table><thead><tr><th scope="col">Symptom</th><th scope="col">Frequency change</th><th scope="col">Strength change</th></tr></thead><tbody><?php foreach ($stats['symptoms'] as $s): ?><tr><th scope="row"><?= e($s['name']) ?></th><td><?php if (!$s['frequency_ready']): ?>Not enough recorded days<?php else: $delta = round($s['late_share']-$s['early_share'],1); ?><?= $delta > 0 ? '↑ Higher' : ($delta < 0 ? '↓ Lower' : 'Unchanged') ?>: <?= number_format($s['early_share'],1) ?>% → <?= number_format($s['late_share'],1) ?>%<br><small><?= $s['early_days'] ?> → <?= $s['late_days'] ?> symptom days; <?= abs($delta) ?> percentage points</small><?php endif ?></td><td><?php if (!$s['strength_ready']): ?><?= !$s['frequency_ready'] ? 'Need a longer period or more recorded days' : 'Need 3 symptom days in each window' ?><?php else: $delta = round($s['strength_change'],1); ?><?= $delta > 0 ? '↑ Stronger' : ($delta < 0 ? '↓ Weaker' : 'Unchanged') ?><?= $delta != 0 ? ': ' . abs($delta) . ' points / 10' : '' ?><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><p class="footnote">Strength first averages repeated entries on each day, then averages those daily values so busy logging days do not dominate.</p></section>
<section class="card"><div class="section-heading"><div><h2>History &amp; streaks</h2><p>All saved history through today, independent of the date filter.</p></div></div><p class="footnote">First-to-last span is a recording history, not continuous symptom duration. Streaks require consecutive calendar dates with entries; a gap breaks the recorded streak.</p>
<div class="history-grid"><?php foreach ($stats['symptoms'] as $s): ?><article class="history-item"><h3><?= e($s['name']) ?></h3><?php if (!$s['first']): ?><p class="muted">No occurrences recorded yet.</p><?php else: ?><dl><dt>First recorded</dt><dd><?= e(dateLabel($s['first'])) ?></dd><dt>Last recorded</dt><dd><?= e(dateLabel($s['last'])) ?></dd><dt>Time since last</dt><dd><?= $s['since'] === 0 ? 'Today' : $s['since'] . ' day' . ($s['since'] === 1 ? '' : 's') . ' ago' ?></dd><dt>First-to-last span</dt><dd><?= $s['span'] ?> calendar <?= $s['span'] === 1 ? 'day' : 'days' ?></dd><dt>Longest recorded streak</dt><dd><?= $s['longest'] ?> <?= $s['longest'] === 1 ? 'day' : 'days' ?><small><?= e(dateLabel($s['streak_start'])) ?>–<?= e(dateLabel($s['streak_end'])) ?></small></dd><dt>Recent recorded streak</dt><dd><?= $s['recent_streak'] ?> days<?= $s['recent_streak'] ? ' · ends ' . e(dateLabel($s['last'])) : '' ?></dd></dl><?php endif ?></article><?php endforeach ?></div></section>
<p class="footnote">Weather and location are saved with individual diary entries. Older entries without context remain valid. These statistics are descriptive and are not a medical assessment.</p>
